/**
 * Get a single Learnpath by ID with all stations.
 * @summary Get Learnpath
 */
export const getLearnpath = (pathId: string, signal?: AbortSignal) => {
  return apiMutator<LearnpathDetailReadDTO>({
    url: `/api/v1/learning-paths/path/${pathId}/`,
    method: "GET",
    signal,
  });
};

export const getGetLearnpathQueryKey = (pathId: string) => {
  return [`/api/v1/learning-paths/path/${pathId}/`] as const;
};

